25	function dateRange(start: string | null, end: string | null): string | null {
26	  if (!start) return null;
27	  const fmt = (iso: string) =>
28	    new Date(iso + "T00:00:00").toLocaleDateString("en-US", { month: "short", day: "numeric" });
29	  const startYear = new Date(start + "T00:00:00").getFullYear();
30	  if (end && end !== start) {
31	    const endYear = new Date(end + "T00:00:00").getFullYear();
32	    return endYear !== startYear
33	      ? `${fmt(start)}, ${startYear} – ${fmt(end)}, ${endYear}`
34	      : `${fmt(start)} – ${fmt(end)}, ${startYear}`;
35	  }
36	  return `${fmt(start)}, ${startYear}`;
37	}
