39	export default async function EventHome({
40	  params,
41	}: {
42	  params: Promise<{ slug: string }>;
43	}) {
44	  const { slug } = await params;
45	  const ctx = await getPlatformContext();
46	  if (!ctx) redirect("/new/signup");
47	  const org = ctx.orgs.find((o) => o.slug === slug);
48	  if (!org) redirect("/new");
49	
50	  const supabase = await v2ServerClient();
51	  const { data } = await supabase
52	    .from("v2_events")
53	    .select("id, name, year, start_date, end_date, status, location")
54	    .eq("org_id", org.id)
55	    .eq("status", "active")
56	    .order("start_date", { ascending: false })
57	    .limit(1)
58	    .maybeSingle();
59	  const event = data as EventRow | null;
60	  const range = event ? dateRange(event.start_date, event.end_date) : null;
61	
62	  // Home modules that mirror a registry feature honor its visibility.
63	  const isAdmin = org.role === "owner" || org.role === "admin";
64	  const resolved = await loadResolvedFeatures(supabase, org.id, event?.id ?? null);
65	  const articlesVisible = isFeatureVisible(resolved, "articles", isAdmin);
66	
67	  // First-run setup checklist — admins only, hidden once done or dismissed.
68	  const onboarding = isAdmin ? await getOnboardingState(supabase, org, isAdmin) : null;
69	
70	  return (
71	    <div className={`${styles.page} ${styles.orgPage}`}>
72	      <PwaInstallBanner appName={org.name} />
73	      {onboarding?.show && (
74	        <OnboardingChecklist
75	          orgId={org.id}
76	          steps={onboarding.steps}
77	          completed={onboarding.completed}
78	          total={onboarding.total}
79	        />
80	      )}
81	      {event ? (
82	        <>
83	          <div className={styles.eventHero}>
84	            <h1 className={`${styles.title} ${styles.eventTitle}`}>{event.name}</h1>
85	          </div>
86	          {(range || event.start_date) && (
87	            <div className={styles.dateBand}>
88	              {range && <span className={styles.dateText}>{range}</span>}
89	              {event.start_date && <Countdown start={event.start_date} end={event.end_date} nowMs={(await v2Now()).getTime()} />}
90	            </div>
91	          )}
92	
93	          {event.location && (
94	            <div className={styles.locationBand}>
95	              <EventLocation location={event.location} />
96	            </div>
97	          )}
98	
99	          <HomeModules
100	            orgId={org.id}
101	            eventId={event.id}
102	            userId={ctx.userId}
103	            slug={slug}
104	            eventName={event.name}
105	            storeUrl={org.store_url}
106	            storeLabel={org.store_label}
107	            storeEnabled={org.store_enabled}
108	            nameDisplay={org.name_display}
109	            articlesVisible={articlesVisible}
110	          />
111	        </>
112	      ) : (
113	        <div className={styles.eventHero}>
114	          <h1 className={styles.title}>No active event</h1>
115	          <p className={styles.lede}>There isn&apos;t an event running right now. Check back soon.</p>
116	        </div>
117	      )}
118	    </div>
119	  );
120	}
