15	/**
16	 * Event-home module stack. Each module is condition-gated: it renders only when
17	 * it has something to say (a birthday today, an article to feature, …). While we
18	 * build out the real data sources everything is STUBBED — a module with no live
19	 * data still renders a labeled preview card (the small "preview" tag) so the
20	 * layout can be designed. Swap `PREVIEW` handling for the real empty-state
21	 * (return null) as each source comes online.
22	 *
23	 * Order follows the agreed home layout:
24	 *   1 Birthdays · 2 Current Article · 3 Registration · 4 Store · 5 Recent Rounds · 6 Ads
25	 */
26	
27	const PREVIEW = true; // while stubbing: show empty modules as labeled previews.
