38	function birthdaysToday(
39	  rows: { v2_profiles: MemberProfile | null }[],
40	  mode: NameMode,
41	  now: Date,
42	): BirthdayPerson[] {
43	  const today = todayInTimezone("America/New_York", now);
44	  const mmdd = `${String(today.month).padStart(2, "0")}-${String(today.day).padStart(2, "0")}`;
45	  return rows
46	    .map((r) => r.v2_profiles)
47	    .filter((p): p is MemberProfile => !!p && !!p.birthdate)
48	    .filter((p) => (p.birthdate as string).slice(5) === mmdd) // YYYY-MM-DD → MM-DD
49	    .map((p) => ({
50	      id: p.id,
51	      name: pickName(p, mode),
52	      avatarUrl: p.avatar_url,
53	      age: ageTurningToday(p.birthdate as string, today.year),
54	    }));
55	}
