91	      .eq("org_id", orgId)
92	      .eq("status", "active")
93	      .is("archived_at", null),
94	    // Latest published article for the org (event-specific scoping comes later).
95	    supabase
96	      .from("v2_articles")
97	      .select(
98	        "id, title, publish_at, image_url, content, image_focal_x, image_focal_y, author:v2_profiles!v2_articles_author_id_fkey(display_name, first_name, last_name, avatar_url)",
99	      )
100	      .eq("org_id", orgId)
101	      .not("publish_at", "is", null)
102	      .lte("publish_at", nowIso)
103	      .order("pinned_at", { ascending: false, nullsFirst: false })
