143	  const ads = (adsRes.data as Ad[] | null) ?? [];
144	  const activity = ((activityRes.data as unknown as (Omit<ActivityRow, "actor"> & {
145	    actor: ActivityRow["actor"] | ActivityRow["actor"][];
146	  })[]) ?? []).map((a) => ({
147	    ...a,
148	    actor: Array.isArray(a.actor) ? a.actor[0] ?? null : a.actor,
149	  })) as ActivityRow[];
150	
151	  const orgSys = (orgSysRes.data as { system_name: string | null; system_avatar_url: string | null } | null) ?? null;
152	  const systemName = orgSys?.system_name?.trim() || "System";
153	  const systemAvatar = orgSys?.system_avatar_url ?? null;
154	
155	  const birthdays = birthdaysToday(
156	    (membersRes.data as unknown as { v2_profiles: MemberProfile | null }[]) || [],
