160	
161	  // Featured article (null until 00185 is applied / an article is published).
162	  const row = articleRes.error ? null : (articleRes.data as ArticleRow | null);
163	  const rowAuthor = row ? (Array.isArray(row.author) ? row.author[0] : row.author) : null;
164	  const article: FeaturedArticle | null = row
165	    ? {
166	        id: row.id,
167	        title: row.title,
168	        publishAt: row.publish_at,
169	        imageUrl: row.image_url,
170	        preview: stripMarkdown(row.content || "") || null,
171	        focalX: row.image_focal_x ?? 50,
172	        focalY: row.image_focal_y ?? 50,
173	        authorName: rowAuthor ? pickName(rowAuthor, nameDisplay) : null,
