1	/**
2	 * The v2 FEATURE CATALOG and registry resolver.
3	 *
4	 * The catalog is the app-side source of truth for *what features exist* (label,
5	 * bucket, icon, blurb, whether it's built yet). The DB table `v2_event_features`
6	 * stores *how a group has configured them* (enabled / pinned / renamed / public /
7	 * availability), scoped per-event and defaulting from the org.
8	 *
9	 * Nothing appears until an admin explicitly enables it (locked IA decision), so
10	 * every non-tier1 feature defaults to `enabled: false`. Tier-1 utilities
11	 * (Chat/Photos/Music/Notifications/Profile) live permanently in the top bar and
12	 * are exempt from opt-in — they're marked `tier1` and rendered "always on."
13	 *
14	 * Adding a feature = add a catalog entry here. No migration needed (feature_key
15	 * is validated against this catalog, not a DB enum). Flip a feature's `status`
16	 * from 'planned' to 'available' when it's actually built and wired.
17	 *
18	 * See docs/v2-information-architecture.md.
19	 */
20	
21	export type FeatureBucket = "scores" | "schedule" | "community" | "stories" | "you";
22	
23	/** 'available' = built & wired; 'planned' = catalogued but not yet portable. */
24	export type FeatureStatus = "available" | "planned";
25	
26	/** How a feature is reached: a routed page, a top-bar drawer, or an external link. */
27	export type FeatureSurface = "route" | "drawer" | "external";
28	
29	export type FeatureAvailability = "always" | "window";
30	
31	/**
32	 * Where a feature is configured:
33	 *   'group' — set once for the whole group (Articles, Chat, Photos, Music,
34	 *             Polls, My Rounds…). Stored as an org-default row (event_id NULL).
35	 *   'event' — set per-event (contests, Schedule, Rooms, Trip Info…). Stored as
36	 *             an event-scoped row.
37	 * The two admin screens (group vs event Features) each show only their scope.
38	 */
39	export type FeatureScope = "group" | "event";
40	
41	export interface FeatureDef {
42	  key: string;
43	  label: string;
44	  bucket: FeatureBucket;
45	  scope: FeatureScope;
46	  /** Icon key resolved by the shared feature-icon map (client) — see FeatureIcon. */
47	  icon: string;
48	  status: FeatureStatus;
49	  surface: FeatureSurface;
50	  /** One-line "what this is" shown in the launcher and config screen. */
51	  blurb: string;
52	  /** Lives in the fixed top utility bar (Chat/Photos/Music/Profile) — never in
53	   *  the launcher or bottom-bar pins. */
54	  topbar?: boolean;
55	  /** Cannot be turned off — reserved for Profile (a member's own account access).
56	   *  Everything else, including Chat/Photos, is toggleable per the group. */
57	  alwaysOn?: boolean;
58	  /** Visible to everyone when the group has no registry row yet (used for Music:
59	   *  on by default but toggleable). Everything else defaults to 'off' (opt-in). */
60	  defaultEnabled?: boolean;
61	  /** Suggested default when a group first exposes it to spectators. */
62	  defaultPublic?: boolean;
63	}
64	
65	export interface BucketDef {
66	  key: FeatureBucket;
67	  label: string;
68	}
69	
70	/** Buckets in display order — the section headers in "Everything" and config. */
71	export const FEATURE_BUCKETS: BucketDef[] = [
72	  { key: "scores", label: "Scores & Games" },
73	  { key: "schedule", label: "Schedule & Logistics" },
74	  { key: "community", label: "Community" },
75	  { key: "stories", label: "Stories & Recognition" },
76	  { key: "you", label: "You" },
77	];
