79	/**
80	 * Every feature the original site offers, bucketed. `status: 'available'` marks
81	 * the ones actually built in v2 today; the rest are 'planned' placeholders so the
82	 * config screen shows the full map and each lights up as it's ported.
83	 */
84	export const FEATURE_CATALOG: FeatureDef[] = [
85	  // ── Scores & Games (contests → per event) ────────────────────────────────
86	  { key: "live_scoring", label: "Live Scoring", bucket: "scores", scope: "event", icon: "flag", status: "planned", surface: "route", blurb: "Score rounds hole-by-hole in real time." },
87	  { key: "scramble", label: "Scramble", bucket: "scores", scope: "event", icon: "users", status: "planned", surface: "route", blurb: "Team scramble scoring & leaderboard." },
88	  { key: "skins", label: "Skins", bucket: "scores", scope: "event", icon: "coins", status: "planned", surface: "route", blurb: "Hole-by-hole skins game." },
89	  { key: "hundred_feet", label: "100 Feet", bucket: "scores", scope: "event", icon: "target", status: "planned", surface: "route", blurb: "Closest-to-100-feet putting contest." },
90	  { key: "daily_games", label: "Daily Games", bucket: "scores", scope: "event", icon: "dice", status: "planned", surface: "route", blurb: "Per-day side games & contests." },
91	  { key: "kgb_cup", label: "KGB Cup", bucket: "scores", scope: "event", icon: "trophy", status: "planned", surface: "route", blurb: "Ryder-Cup-style team competition." },
