152	/** A catalog feature merged with its effective configuration for an event. */
153	export interface ResolvedFeature {
154	  def: FeatureDef;
155	  visibility: FeatureVisibility;
156	  pinned: boolean;
157	  navOrder: number;
158	  label: string; // label_override || def.label
159	  public: boolean;
