166	function baseResolved(def: FeatureDef): ResolvedFeature {
167	  return {
168	    def,
169	    // alwaysOn (Profile) can't be turned off; a few (Chat/Photos/Music) default
170	    // to everyone but stay toggleable; everything else is off (opt-in).
171	    visibility: def.alwaysOn || def.defaultEnabled ? "everyone" : "off",
172	    pinned: false,
173	    navOrder: 0,
174	    label: def.label,
175	    public: !!def.defaultPublic,
176	    availability: "always",
177	    availableFrom: null,
178	    availableUntil: null,
179	    source: "default",
180	  };
181	}
182	
183	function applyRow(acc: ResolvedFeature, row: FeatureRow, source: FeatureSource): ResolvedFeature {
184	  return {
185	    ...acc,
186	    visibility: acc.def.alwaysOn ? "everyone" : row.visibility,
187	    pinned: row.pinned,
188	    navOrder: row.nav_order,
189	    label: row.label_override?.trim() || acc.def.label,
190	    public: row.public,
191	    availability: row.availability,
192	    availableFrom: row.available_from,
193	    availableUntil: row.available_until,
194	    source,
195	  };
196	}
