198	/** Is a feature visible to this viewer? ('admins' requires org admin/owner.) */
199	export function isVisibleTo(f: ResolvedFeature, viewerIsAdmin: boolean): boolean {
200	  if (f.visibility === "everyone") return true;
201	  if (f.visibility === "admins") return viewerIsAdmin;
202	  return false;
203	}
