205	/**
206	 * Merge catalog defaults < org defaults (event_id null) < event overrides for a
207	 * given event, returning every catalog feature in catalog order.
208	 */
209	export function resolveFeatures(rows: FeatureRow[], eventId: string): ResolvedFeature[] {
210	  const orgRows = new Map(rows.filter((r) => r.event_id === null).map((r) => [r.feature_key, r]));
211	  const eventRows = new Map(rows.filter((r) => r.event_id === eventId).map((r) => [r.feature_key, r]));
212	
213	  return FEATURE_CATALOG.map((def) => {
214	    let acc = baseResolved(def);
215	    const org = orgRows.get(def.key);
216	    if (org) acc = applyRow(acc, org, "org");
217	    const ev = eventRows.get(def.key);
218	    if (ev) acc = applyRow(acc, ev, "event");
219	    return acc;
220	  });
221	}
