223	/** Is a visible feature currently within its availability window? */
224	export function isFeatureActive(
225	  f: ResolvedFeature,
226	  viewerIsAdmin: boolean,
227	  now = new Date(),
228	): boolean {
229	  if (!isVisibleTo(f, viewerIsAdmin)) return false;
230	  if (f.availability !== "window") return true;
231	  const t = now.getTime();
232	  if (f.availableFrom && t < new Date(f.availableFrom).getTime()) return false;
233	  if (f.availableUntil && t > new Date(f.availableUntil).getTime()) return false;
234	  return true;
235	}
