307	/** A resolved feature flattened for the shell (bottom bar + launcher). */
308	export interface NavFeature {
309	  key: string;
310	  label: string;
311	  icon: string;
312	  bucket: FeatureBucket;
313	  blurb: string;
314	  href: string | null;
315	  /** Navigable right now (has a destination and within any availability window). */
316	  active: boolean;
317	  /** Why it isn't navigable ("Coming soon" / "Opens Mar 3" / "Closed"), or null. */
318	  lockReason: string | null;
319	  /** Shown only to admins (visibility='admins') — badge it so they know. */
320	  adminOnly: boolean;
321	}
322	
323	function lockReasonFor(f: ResolvedFeature, href: string | null, now: Date): string | null {
324	  if (f.availability === "window") {
325	    if (f.availableFrom && now.getTime() < new Date(f.availableFrom).getTime()) {
326	      return `Opens ${fmtShortDate(f.availableFrom)}`;
327	    }
328	    if (f.availableUntil && now.getTime() > new Date(f.availableUntil).getTime()) {
329	      return "Closed";
330	    }
331	  }
332	  return href ? null : "Coming soon";
333	}
334	
335	export function toNavFeature(slug: string, f: ResolvedFeature, now = new Date()): NavFeature {
336	  const href = featureHref(slug, f.def);
337	  const lockReason = lockReasonFor(f, href, now);
338	  return {
339	    key: f.def.key,
340	    label: f.label,
341	    icon: f.def.icon,
342	    bucket: f.def.bucket,
343	    blurb: f.def.blurb,
344	    href,
345	    active: lockReason === null,
346	    lockReason,
347	    adminOnly: f.visibility === "admins",
348	  };
349	}
