357	/**
358	 * The complete shell nav for an event: the (≤3) bottom-bar pins and the
359	 * "Everything" launcher grouped by bucket. Availability windows are resolved
360	 * against `now` on the server, so the client renders static state (no Date in
361	 * render). Falls back to empty arrays when nothing is enabled.
362	 */
363	export function buildEventNav(
364	  slug: string,
365	  resolved: ResolvedFeature[],
366	  viewerIsAdmin: boolean,
367	  now = new Date(),
368	): { pinned: NavFeature[]; launcher: LauncherGroup[] } {
369	  const pinned = pinnedFeatures(resolved, viewerIsAdmin).map((f) => toNavFeature(slug, f, now));
370	  const launcher = launcherBuckets(resolved, viewerIsAdmin).map((g) => ({
371	    bucketKey: g.bucket.key,
372	    bucketLabel: g.bucket.label,
373	    features: g.features.map((f) => toNavFeature(slug, f, now)),
374	  }));
375	  return { pinned, launcher };
376	}
